<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $title ?? 'Administración' }} · Saturnext</title><style>
:root{--navy:#0d1b2a;--blue:#1769aa;--ink:#17212b;--muted:#607083;--line:#dbe4ee;--bg:#f6f8fb;--green:#0c8f61;--red:#b42318;--amber:#a96600}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.app{min-height:100vh;display:grid;grid-template-columns:245px minmax(0,1fr)}.sidebar{background:var(--navy);color:#fff;padding:26px 16px}.brand{font-size:19px;font-weight:850;white-space:nowrap;padding:0 10px 26px}.brand span{color:#75c8ff}.brand small{display:block;color:#b9d8ef;font-size:12px;font-weight:600;margin-top:5px}.nav{display:flex;flex-direction:column;gap:5px}.nav a{color:#c8deef;text-decoration:none;font-size:14px;padding:11px 12px;border-radius:8px}.nav a:hover,.nav a.active{background:#1e3a55;color:#fff}.shell{max-width:1180px;width:100%;margin:30px auto;padding:0 28px}.eyebrow{color:var(--blue);font-size:12px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;margin:0}h1{font-size:32px;letter-spacing:-1px;margin:5px 0}h2{font-size:18px;margin:0}p{color:var(--muted);line-height:1.5}.panel{background:#fff;border:1px solid var(--line);border-radius:14px;padding:20px;box-shadow:0 5px 18px rgba(26,51,77,.05)}.panel+.panel{margin-top:18px}.button{display:inline-block;border:0;border-radius:8px;background:var(--blue);color:#fff;padding:10px 12px;font:inherit;font-weight:750;cursor:pointer;text-decoration:none}.button:hover{background:#0e578e}.button.light{background:#edf5fb;color:#155a8d}.button.green{background:var(--green)}.button.danger{background:#fff1f0;color:var(--red)}.button.small{padding:6px 8px;font-size:12px}.alert{background:#e8f8ef;color:#096442;border:1px solid #bee7d0;border-radius:9px;padding:11px 13px;margin:16px 0}.sub{display:block;font-size:13px;color:var(--muted)}.badge{display:inline-block;border-radius:999px;padding:5px 9px;font-size:12px;font-weight:800;background:#e7f7ef;color:#08764e}.badge.blocked,.badge.suspended,.badge.failed{background:#fff1f0;color:var(--red)}.badge.pending,.badge.running{background:#fff4dd;color:var(--amber)}label{display:block;font-size:12px;font-weight:750;margin:12px 0 5px}input,select{width:100%;border:1px solid #cbd8e5;border-radius:8px;padding:9px 10px;font:inherit;background:#fff}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px}.wide{grid-column:1/-1}.checks{display:flex;flex-wrap:wrap;gap:12px}.checks label{display:flex;align-items:center;gap:5px;font-weight:600}.checks input{width:auto}.error{font-size:12px;color:var(--red);margin-top:4px}table{width:100%;border-collapse:collapse}th{text-align:left;color:#77889a;font-size:11px;text-transform:uppercase;letter-spacing:.08em;border-bottom:1px solid var(--line);padding:9px 6px}td{font-size:14px;padding:12px 6px;border-bottom:1px solid #edf1f5;vertical-align:top}.link{color:var(--blue);font-weight:750;text-decoration:none}@media(max-width:760px){.app{display:block}.sidebar{padding:15px}.brand{padding:0 4px 10px}.nav{flex-direction:row;overflow:auto}.nav a{white-space:nowrap;padding:8px 10px}.shell{padding:0 14px;margin:22px auto}.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}}
</style></head><body><div class="app"><aside class="sidebar"><div class="brand">Saturn<span>ext</span><small>Administración SaaS</small></div><nav class="nav"><a class="{{ request()->routeIs('dashboard') ? 'active' : '' }}" href="{{ route('dashboard') }}">Inicio</a><a class="{{ request()->routeIs('companies.*') ? 'active' : '' }}" href="{{ route('companies.index') }}">Compañías</a><a class="{{ request()->routeIs('catalog.*') ? 'active' : '' }}" href="{{ route('catalog.index') }}">Servicios y planes</a><a class="{{ request()->routeIs('users.*') ? 'active' : '' }}" href="{{ route('users.index') }}">Usuarios</a><a class="{{ request()->routeIs('payments.*') || request()->routeIs('companies.payments.*') ? 'active' : '' }}" href="{{ route('payments.index') }}">Pagos</a></nav><div style="margin:26px 10px 0;padding-top:16px;border-top:1px solid #31516a;font-size:12px;color:#c8deef">{{ auth()->user()->email }}<form method="post" action="{{ route('logout') }}" style="margin-top:9px">@csrf<button type="submit" style="border:0;background:transparent;padding:0;color:#fff;font:inherit;font-weight:750;cursor:pointer">Cerrar sesión</button></form></div></aside><main class="shell">@if(session('success'))<div class="alert">{{ session('success') }}</div>@endif @if(session('error'))<div class="alert" style="background:#fff1f0;color:var(--red);border-color:#f2c5c1">{{ session('error') }}</div>@endif @yield('content')</main></div></body></html>
